"""A thing with an id"""
interface Node { id: ID! }
interface Named implements Node { id: ID! name: String }
enum Episode { NEWHOPE EMPIRE JEDI @deprecated(reason: "old") }
type Human implements Named & Node { id: ID! name: String friends: [Character] homePlanet: String appearsIn: [Episode!]! height(unit: Unit = METER): Float }
type Droid implements Named & Node { id: ID! name: String friends: [Character] primaryFunction: String appearsIn: [Episode!]! }
union Character = Human | Droid
enum Unit { METER FOOT }
input Review { stars: Int! commentary: String tags: [String!] = ["x"] legacy: String @deprecated(reason: "unused") }
input Lookup @oneOf { a: String b: Int }
scalar Date @specifiedBy(url: "https://example.com/date")
type Query {
  hero(episode: Episode): Character
  human(id: ID!): Human
  droids: [Droid!]!
  nodes(ids: [ID!]!): [Node]!
  echo(i: Int, f: Float, s: String, b: Boolean, id: ID, e: Episode, r: Review, l: [[Int]]): String
  nonNull: String!
  wrong: Int
  date: Date
  list: [Int!]
  deep: Query
  find(by: Lookup!): String
  old(x: Int @deprecated(reason: "gone"), y: Int): String
  id5: ID
  idList: [ID]
}
type Mutation { addReview(episode: Episode, review: Review!): String }
type Subscription { reviews: String }

